// Synthetic regression check: confirm the probe would catch
// the #419 pattern if it landed. We write a temp Go file
// into the appshell dir, run the probe, assert it flags the
// fixture, then clean up.

import { strict as assert } from 'node:assert';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, sep } from 'node:path';

const FIXTURE = `package appshell

// Synthetic fixture that exhibits the #419 closure-capture
// race pattern. The probe MUST flag this as a high-confidence
// candidate. This file is generated by
// discover_closure_race_fixture_test.mjs and deleted at the
// end of the run; it should never exist in the tree.
func fixtureForClosureRaceProbe() {
	var jobID string
	jobID = a.jobs.Start("synthetic_fixture", func(ctx context.Context, p *jobs.Progress) error {
		a.jobs.SetResultPath(jobID, "/tmp/synthetic")
		return nil
	})
}
`;

const tmp = mkdtempSync(join(tmpdir(), 'closure-race-fixture-'));
const target = join(tmp, 'closure_race_fixture.go');
writeFileSync(target, FIXTURE);

// Append the temp file path to a known probe-input list
// (the probe walks internal/appshell/*.go). Copy the real
// appshell dir to a sandbox, append the fixture, run the
// probe against the sandbox.
//
// Simpler approach: since the probe scans a hardcoded path,
// we instead inline-eval the probe functions against the
// fixture by patching the source path. That's too invasive.
// Instead, write the fixture into the actual appshell dir,
// run the probe, capture the output, delete the fixture,
// and assert the output flagged it.
const ROOT = new URL('..', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1');
const realTarget = join(ROOT, 'internal', 'appshell', 'closure_race_fixture_test_fixture.go');
writeFileSync(realTarget, FIXTURE);

import { spawnSync } from 'node:child_process';
const PROBE = join(ROOT, 'audit/discover_closure_race.mjs');
const r = spawnSync('node', [PROBE], { encoding: 'utf8' });

let exitCode = 0;
try {
  // The fixture contains `var jobID string; jobID = a.jobs.Start(...)`
  // and the closure reads `jobID`. Probe MUST flag this as
  // high-confidence.
  assert.match(r.stdout, /\[high\][^\n]*closure_race_fixture_test_fixture\.go[^\n]*reads outer-scope `jobID`/,
    `probe did not flag the synthetic fixture:\n${r.stdout}`);
  console.log('  ✓ probe catches synthetic #419 fixture');
} catch (err) {
  console.log(`  ✗ probe missed synthetic #419 fixture`);
  console.log(`    ${err.message}`);
  exitCode = 1;
} finally {
  rmSync(realTarget);
  rmSync(tmp, { recursive: true, force: true });
}

process.exit(exitCode);